DNS_LIMIT = 4096


def read_config(path, evidence):
    raw = strict_json(file_bytes(path, protected=True))
    fields(
        raw,
        "profile evidence release_sha controller_ed25519 generation uid gid "
        "route_path route_sha ca_path ca_sha db spend",
        "CONFIG_SCHEMA_INVALID",
    )
    require(
        raw["profile"] == PROFILE and raw["evidence"] == evidence,
        "FIXTURE_CONFIGURATION_REQUIRED",
    )
    require(
        all(
            hexdigest(raw[key])
            for key in ("release_sha", "controller_ed25519", "route_sha", "ca_sha")
        )
        and hexdigest(raw["generation"], 32)
        and all(integer(raw[key], 1, 2**32 - 2) for key in ("uid", "gid"))
        and all(type(raw[key]) is str for key in ("route_path", "ca_path")),
        "CONFIG_BINDING_INVALID",
    )
    db, spend = Pin.parse(raw["db"]), Pin.parse(raw["spend"])
    a, b = db.path.parent, spend.path.parent
    require(
        db.uid == spend.uid == raw["uid"]
        and a != b
        and not a.is_relative_to(b)
        and not b.is_relative_to(a)
        and (db.device, db.inode) != (spend.device, spend.inode),
        "INDEPENDENT_LOCAL_SPEND_PATH_REQUIRED",
    )
    return Configuration(
        path,
        digest(raw),
        raw["release_sha"],
        bytes.fromhex(raw["controller_ed25519"]),
        raw["generation"],
        raw["uid"],
        raw["gid"],
        Path(raw["route_path"]),
        raw["route_sha"],
        Path(raw["ca_path"]),
        raw["ca_sha"],
        db,
        spend,
    )


def check_envelope(raw, config, *, schema, domain, evidence):
    fields(raw, "schema scope controller_signature", "S2V2_ENVELOPE_REQUIRED")
    require(
        raw["schema"] == schema and hexdigest(raw["controller_signature"], 128),
        "S2V2_ENVELOPE_REQUIRED",
    )
    scope = raw["scope"]
    fields(
        scope,
        "profile capability evidence authority requests run_id not_before_ms expires_ms "
        "release_sha config_sha generation route_sha ca_sha max_attempts max_weight retries "
        "redirects rolling",
        "S2V2_SCOPE_SCHEMA_INVALID",
    )
    try:
        Ed25519PublicKey.from_public_bytes(config.controller_key).verify(
            bytes.fromhex(raw["controller_signature"]), domain + canonical(scope)
        )
    except (InvalidSignature, ValueError) as exc:
        raise Denied("CONTROLLER_SIGNATURE_INVALID") from exc
    require(
        (scope["profile"], scope["capability"], scope["evidence"], scope["authority"])
        == (PROFILE, CAPABILITY, evidence, AUTHORITY)
        and scope["requests"] == GETS
        and all(
            type(scope[key]) is int
            for key in ("max_attempts", "max_weight", "retries", "redirects")
        )
        and (scope["max_attempts"], scope["max_weight"], scope["retries"], scope["redirects"])
        == (2, 2, 0, 0),
        "S2_ONLY_SCOPE_REQUIRED",
    )
    require(
        (
            scope["release_sha"],
            scope["config_sha"],
            scope["generation"],
            scope["route_sha"],
            scope["ca_sha"],
        )
        == (
            config.release_sha,
            config.canonical_sha,
            config.generation,
            config.route_sha,
            config.ca_sha,
        ),
        "S2V2_SCOPE_BINDING_MISMATCH",
    )
    require(
        hexdigest(scope["run_id"], 32)
        and all(integer(scope[key], 1, 2**63 - 1) for key in ("not_before_ms", "expires_ms"))
        and 0 < scope["expires_ms"] - scope["not_before_ms"] <= WINDOW_MS,
        "S2V2_VALIDITY_INVALID",
    )
    b = scope["rolling"]
    fields(
        b,
        "window_ms count_cap weight_cap shared_count_upper shared_weight_upper count_headroom "
        "weight_headroom shared_observed_ms",
        "ROLLING_SCOPE_INVALID",
    )
    require(
        integer(b["window_ms"], WINDOW_MS, WINDOW_MS)
        and integer(b["count_cap"], 2, 96)
        and integer(b["weight_cap"], 2, 120)
        and integer(b["shared_observed_ms"], 1, 2**63 - 1)
        and all(integer(b[key], 0, 120) for key in ("shared_count_upper", "shared_weight_upper"))
        and all(integer(b[key], 1, 120) for key in ("count_headroom", "weight_headroom")),
        "SHARED_HEADROOM_STALE_OR_UNKNOWN",
    )
    return Grant(scope, digest(scope), digest(raw))


def runtime_identity(config):
    require(
        os.geteuid() == config.runtime_uid
        and os.getegid() == config.runtime_gid
        and not os.getgroups(),
        "RUNTIME_UID_GID_MISMATCH",
    )
    status = dict(
        line.split(":", 1)
        for line in Path("/proc/self/status").read_text().splitlines()
        if ":" in line
    )
    require(
        all(int(status[key], 16) == 0 for key in ("CapEff", "CapPrm", "CapAmb"))
        and status["NoNewPrivs"].strip() == "1",
        "EXCESS_RUNTIME_PRIVILEGES",
    )
    for pin in (config.db, config.spend):
        result = subprocess.run(
            ["/usr/bin/findmnt", "-n", "-o", "FSTYPE", "-T", str(pin.path.parent)],
            capture_output=True,
            text=True,
            timeout=2,
            check=False,
        )
        require(
            result.returncode == 0 and result.stdout.strip() == "ext4", "WSL_EXT4_STATE_REQUIRED"
        )
    require("wsl2" in os.uname().release.lower(), "WSL2_RUNTIME_REQUIRED")


def confirm(grant, clock):
    tty_check()
    require(termios.tcgetattr(0)[3] & termios.ICANON, "CANONICAL_TTY_REQUIRED")
    now = clock.now()
    grant.check_time(now)
    nonce = secrets.token_hex(16)
    expected = f"APPROVE {grant.run_id} {grant.grant_sha} {nonce}"
    termios.tcflush(0, termios.TCIFLUSH)
    print(f"{grant.scope['evidence']} {grant.scope['authority']}", flush=True)
    for row in grant.scope["requests"]:
        print(row["method"], row["path"], flush=True)
    print(f"release {grant.scope['release_sha']} scope {grant.scope_sha}", flush=True)
    print(f"expires_ms {grant.scope['expires_ms']} max_attempts 2 max_weight 2", flush=True)
    b = grant.budget
    print(
        f"rolling_count {b['count_cap']} rolling_weight {b['weight_cap']} "
        f"shared_upper {b['shared_count_upper']}/{b['shared_weight_upper']} "
        f"headroom {b['count_headroom']}/{b['weight_headroom']}",
        flush=True,
    )
    print(f"CHALLENGE {expected}", flush=True)
    deadline = time.monotonic() + min(30, (grant.scope["expires_ms"] - now) / 1000)
    ready, _, _ = select.select([0], [], [], max(0, deadline - time.monotonic()))
    require(ready and time.monotonic() < deadline, "CONSOLE_CONFIRMATION_TIMEOUT")
    tty_check()
    typed = os.read(0, 512)
    require(
        hmac.compare_digest(typed, expected.encode("ascii") + b"\n"),
        "CONSOLE_CONFIRMATION_MISMATCH",
    )
    grant.check_time(clock.now())


def route_fingerprint(proc_ipv4_routes: str) -> str:
    """Fingerprint the stable fields of Linux's visible IPv4 main routing table."""
    lines = proc_ipv4_routes.splitlines()
    require(bool(lines) and lines[0].split()[:4] == ["Iface","Destination","Gateway","Flags"],
            "EGRESS_ROUTE_TABLE_INVALID")
    stable = []
    for line in lines[1:]:
        columns = line.split()
        require(len(columns) == 11, "EGRESS_ROUTE_TABLE_INVALID")
        stable.append(" ".join(columns[:4] + columns[6:]))
    require(bool(stable), "EGRESS_ROUTE_TABLE_EMPTY")
    return sha(("\n".join(sorted(stable))+"\n").encode("ascii"))


def _name(packet, position):
    labels = []
    visited = set()
    end = None
    while True:
        require(0 <= position < len(packet) and position not in visited and len(visited) <= 128,
                "DNS_NAME_INVALID")
        visited.add(position)
        count = packet[position]
        position += 1
        if count == 0:
            return b".".join(labels).lower(), end if end is not None else position
        if count & 0xC0 == 0xC0:
            require(position < len(packet), "DNS_NAME_INVALID")
            pointer = ((count & 0x3F) << 8) | packet[position]
            require(pointer < position-1, "DNS_NAME_INVALID")
            end = position+1 if end is None else end
            position = pointer
        else:
            require(count <= 63 and position+count <= len(packet) and len(labels) <= 32, "DNS_NAME_INVALID")
            labels.append(packet[position:position+count])
            position += count


def dns_answers(packet, query_id, hostname):
    require(12 <= len(packet) <= DNS_LIMIT, "DNS_REPLY_INVALID")
    ident, flags, questions, answers, _, _ = struct.unpack_from("!6H", packet)
    require(ident == query_id and flags & 0xFA0F == 0x8000 and questions == 1 and 1 <= answers <= 64,
            "DNS_REPLY_INVALID")
    question, pos = _name(packet, 12)
    origin = hostname.encode("ascii")
    require(question == origin and packet[pos:pos+4] == struct.pack("!HH", 1, 1), "DNS_QUESTION_MISMATCH")
    pos += 4
    aliases = {}
    addresses = {}
    for _ in range(answers):
        name, pos = _name(packet, pos)
        require(pos+10 <= len(packet), "DNS_REPLY_TRUNCATED")
        typ, cls, _, size = struct.unpack_from("!HHIH", packet, pos)
        pos += 10
        require(pos+size <= len(packet) and cls == 1, "DNS_REPLY_INVALID")
        if typ == 5:
            alias, end = _name(packet, pos)
            require(end == pos+size and name not in aliases and bool(alias), "DNS_ALIAS_INVALID")
            aliases[name] = alias
        elif typ == 1:
            require(size == 4, "DNS_ADDRESS_INVALID")
            addresses.setdefault(name, set()).add(str(ipaddress.IPv4Address(packet[pos:pos+4])))
        pos += size
    name = origin
    visited = set()
    while name in aliases:
        require(name not in visited and name not in addresses, "DNS_ALIAS_INVALID")
        visited.add(name)
        name = aliases[name]
    require(bool(addresses.get(name)), "DNS_NO_BOUND_ADDRESS")
    return tuple(sorted(addresses[name]))
